import React, { useState } from 'react';
import '../styles/theme.css';

export default function Expenses() {
  const [formData, setFormData] = useState({
    category: 'Transportation & Freight',
    amount: '12500',
    paidTo: 'Shree Ji Transport',
    date: '2026-09-01',
    notes: 'Freight charges for Indore Mandi delivery'
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  return (
    <div style={{ padding: '20px', maxWidth: '480px', margin: '0 auto', fontFamily: 'Segoe UI, sans-serif' }}>
      
      {/* Header */}
      <h2 style={{ color: '#1B4D3E', marginBottom: '20px' }}>Record Expense</h2>

      <form style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        
        {/* Expense Category */}
        <div>
          <label style={labelStyle}>Expense Category</label>
          <select name="category" value={formData.category} onChange={handleChange} style={inputStyle}>
            <option value="Transportation & Freight">Transportation & Freight</option>
            <option value="Labor & Hamali">Labor & Hamali</option>
            <option value="Godown Rent & Maintenance">Godown Rent & Maintenance</option>
            <option value="Electricity & Utilities">Electricity & Utilities</option>
            <option value="Office & Miscellaneous">Office & Miscellaneous</option>
          </select>
        </div>

        {/* Amount */}
        <div>
          <label style={labelStyle}>Amount (₹)</label>
          <input type="number" name="amount" value={formData.amount} onChange={handleChange} style={{ ...inputStyle, fontSize: '18px', fontWeight: 'bold', color: '#C0392B' }} />
        </div>

        {/* Paid To */}
        <div>
          <label style={labelStyle}>Paid To / Vendor Name</label>
          <input type="text" name="paidTo" value={formData.paidTo} onChange={handleChange} style={inputStyle} />
        </div>

        {/* Date */}
        <div>
          <label style={labelStyle}>Date</label>
          <input type="date" name="date" value={formData.date} onChange={handleChange} style={inputStyle} />
        </div>

        {/* Notes */}
        <div>
          <label style={labelStyle}>Description / Notes</label>
          <textarea name="notes" rows="3" value={formData.notes} onChange={handleChange} style={{ ...inputStyle, resize: 'none' }} />
        </div>

      </form>

      {/* Submit Button */}
      <button style={{ width: '100%', background: '#1B4D3E', color: '#FFF', padding: '14px', border: 'none', borderRadius: '12px', fontWeight: 'bold', fontSize: '16px', marginTop: '25px', cursor: 'pointer', boxShadow: '0 4px 10px rgba(0,0,0,0.1)' }}>
        Save Expense Entry
      </button>

    </div>
  );
}

const labelStyle = { display: 'block', fontSize: '12px', fontWeight: '600', color: '#555', marginBottom: '6px' };
const inputStyle = { width: '100%', padding: '12px', borderRadius: '10px', border: '1px solid #EAE5D9', background: '#FFF', fontSize: '14px', boxSizing: 'border-box' };
